import FadeIn from './FadeIn'; import SectionHeader from './SectionHeader';
const projects = [{ n:'01', name:'NextStep', type:'Centralized university management platform', stack:'React.js · Team collaboration · Frontend', link:'https://github.com/kavishka608/NextStep.git', screen:'next' }, { n:'02', name:'SpareHubLK', type:'Automotive parts e-commerce solution', stack:'PHP · MySQL · JavaScript', link:'https://github.com/kavishka608/sparehublk.com.git', screen:'spare' }];
export default function Projects() { return <section id="projects" className="section"><FadeIn><SectionHeader eyebrow="03 / SELECTED WORK" title="Learning by making." copy="A selection of projects where I applied development fundamentals to useful user experiences." /></FadeIn><div className="project-list">{projects.map((p, i) => <FadeIn key={p.name} direction={i ? 'right' : 'left'}><article className="project"><div className={`project-screen ${p.screen}`}><div className="browser"><i></i><i></i><i></i></div><div className="screen-content"><b>{p.name}</b><span></span><span></span><span></span></div></div><div className="project-info"><span className="project-number">{p.n}</span><h3>{p.name}</h3><p>{p.type}</p><small>{p.stack}</small><a href={p.link} target="_blank" rel="noreferrer">View on GitHub <b>↗</b></a></div></article></FadeIn>)}</div></section>; }
